# -*- coding: utf-8 -*-
# 20 Nov records: authored fields only; ids/DOIs/titles come from cache via _gen.py
add(4, sub="CVM", tier="A", basis="Not stated",
    short="Shenzhen 493,388 adults: PM2.5 HR 1.054 per IQR (5.0 ug/m3) for CKM-syndrome progression; O3 the steadier signal",
    design="Prospective cohort", pm="Preceding-365-day mean PM2.5 and O3, updated at each risk interval; per IQR (PM2.5 5.008 ug/m3, O3 7.431 ug/m3); exposure source not stated in abstract",
    geo="China (Shenzhen)", endpoint="Nonfatal forward progression of cardiovascular-kidney-metabolic (CKM) syndrome stages",
    affil="Shenzhen Center for Chronic Disease Control, China; Shenzhen Center for Chronic Disease Control, China",
    n="Shenzhen Healthy Aging Research Cohort, 2018-2024: 493,388 participants, 1,029,004 risk intervals and 162,083 forward CKM-stage transitions; multistate Cox models with time-updated 365-day mean exposures. Per IQR of PM2.5 (5.0 ug/m3), HR 1.054 (95% CI 1.030-1.078) for overall progression, 1.073 (1.030-1.118) for early (to stages 1-2) and 1.055 (1.027-1.085) for advanced (to stages 3-4). O3 per IQR (7.4 ug/m3) gave larger and steadier HRs (overall 1.151, 1.138-1.165); PM2.5 estimates moved with model specification in six-pollutant and common-sample analyses. Weakness: progression is defined by examination-visit staging, so visit frequency (itself tied to health-seeking) shapes event capture; exposure model unnamed in the abstract. Relevance: the PM2.5 signal is specification-sensitive at a 5 ug/m3 contrast, i.e. within typical uncorrected low-cost-sensor error.")
add(14, sub="CVM", tier="A", basis="Model (CTM / LUR / ML)",
    short="14 European cohorts, >29 million people: IHD incidence +1.4% per quartile PM2.5 in administrative cohorts; adult cohorts positive but non-significant",
    design="Multi-cohort meta-analysis", pm="Residential PM2.5, PM10, NO2 plus built-environment exposome (greenspace, blue space, imperviousness, walkability); per one-quartile increment; time-varying",
    geo="Europe (11 countries)", endpoint="Incident ischemic heart disease",
    affil="Karolinska Institutet, Sweden; not stated",
    n="Eight traditional adult cohorts and six administrative cohorts from 11 European countries, >29 million participants, 464,386 incident IHD cases; time-varying Cox models for single exposures and quantile g-computation for domains, random-effects meta-analysis by cohort type. In administrative cohorts a one-quartile increment was associated with IHD incidence +1.4% (95% CI 0.8-1.9%) for PM2.5, +0.9% (0.1-1.7%) for PM10 and +1.7% (1.0-2.4%) for NO2; the air-pollution domain jointly +2.5% (1.9-3.1%). Adult cohorts, which carry individual confounder data, gave positive but non-significant estimates. Weakness: the significant estimates come from administrative cohorts with the thinnest confounder control (no smoking, BMI), and a quartile increment differs in ug/m3 across countries. Relevance: effects of this size need exposure contrasts resolved at the scale of address-level models; sensor networks can validate within-city gradients those models smooth.")
add(18, sub="REPR", tier="A", basis="Model (CTM / LUR / ML)",
    short="New Jersey 1.18 million conceptions: weekly PM2.5 lowers live-birth-identified conceptions, RR 0.993 per 10 ug/m3 at gestational week 21",
    design="Time-series (DLNM, quasi-Poisson)", pm="Population-weighted county weekly PM2.5 from modelled air-quality data; per 10 ug/m3; lags from LMP to week 40",
    geo="USA (New Jersey)", endpoint="Pregnancy loss, proxied by weekly counts of live-birth-identified conceptions (LBIC)",
    affil="Yale School of the Environment, USA; Yale School of the Environment, USA",
    n="Time-series of weekly live-birth-identified conceptions (LBIC) in all 21 New Jersey counties, LMP dates 2000-2016 (n = 1,179,217 births), quasi-Poisson DLNM over gestational weeks 0-40, adjusted for trend and meteorology. Higher weekly PM2.5 reduced LBIC counts (i.e. more loss); the strongest lag was week 21, RR 0.993 (95% CI 0.990-0.995) per 10 ug/m3. Assuming 10-50% of conceptions are lost, a 10 ug/m3 increase across weeks 0-40 implies 5.2 (3.9-6.6) to 9.3 (7.1-11.9) losses per 1,000 conceptions per week. Weakness: losses are inferred from missing births, so conception-rate shifts and fertility timing are indistinguishable from loss; county-weekly modelled PM2.5 is coarse. Relevance: weekly windows are exactly where county averages fail and residence-level sensing would sharpen exposure.")
add(3, sub="NEU", tier="A", basis="Model (CTM / LUR / ML)",
    short="Helsinki FINRISK 5487 adults at ~1 ug/m3 source-specific PM2.5: no dementia association for traffic exhaust (HR 0.95 per 0.1 ug/m3); wood-combustion HRs elevated but imprecise",
    design="Prospective cohort (registry linkage)", pm="Dispersion-modelled residential PM2.5 from vehicular exhaust (mean 1.06 ug/m3) and residential wood combustion (0.45 ug/m3); 3-15-year averages; per 0.1 ug/m3",
    geo="Finland (Helsinki, Vantaa)", endpoint="Incident dementia and Alzheimer disease (registers)",
    affil="University of Eastern Finland, Finland; University of Eastern Finland, Finland",
    n="FINRISK participants from Helsinki and Vantaa (surveys 1992-2012, n = 5,487) followed to 2022 in registers; 601 incident dementia and 500 AD cases; Cox models with modelled source-specific outdoor PM2.5 at the address. Means were 1.06 ug/m3 (SD 0.95) from vehicle exhaust and 0.45 (0.21) from residential wood combustion. Per 0.1 ug/m3, dementia HR 0.95 (95% CI 0.85-1.05) for exhaust and 1.23 (0.79-1.92) for wood combustion, the latter consistently above 1 across models; no AD associations. Weakness: exposure contrasts of tenths of a ug/m3 are at or below dispersion-model error, and ~600 cases cannot resolve modest HRs. Relevance: source-resolved contrasts this small are beyond any optical sensor; wood-smoke specificity needs composition (levoglucosan, BC-type) rather than mass.")
add(1, sub="EXPO", tier="B", basis="Personal / wearable",
    short="Fuzhou 247 adults >=60, 72-h personal PM2.5: Bayesian LASSO R2 0.48, RMSE 19.3 ug/m3; passive smoking +16.2 ug/m3 the largest predictor",
    design="Personal monitoring + microenvironment model", pm="72-h personal PM2.5 with concurrent outdoor PM2.5; questionnaire residential, behavioural and time-activity predictors",
    geo="China (Fuzhou)", endpoint="Personal PM2.5 exposure prediction",
    affil="Fujian Medical University, China; Fujian Medical University, China",
    n="247 community-dwelling adults aged >=60 in Fuzhou wore personal PM2.5 monitors for one 72-h session (summer or winter) with concurrent outdoor PM2.5 and questionnaire predictors; Bayesian LASSO. Bayesian R2 0.481 (95% CrI 0.412-0.539), RMSE 19.26 ug/m3 (18.80-19.88). Predictors with CrIs excluding zero: passive smoking only +16.2 ug/m3 (7.9-24.5), current smoking +12.9 (7.0-18.8), residence near a major road +7.4 (0.7-14.2), outdoor PM2.5 per SD +6.5 (3.8-9.4); directions stable across repeated cross-validation. Weakness: one 72-h session per person, so within-person seasonal variability is confounded with between-person predictors; monitor type and its humidity correction are not given in the abstract. Relevance: outdoor PM2.5 explains less of personal exposure than tobacco smoke at home - the argument for wearable or indoor sensors over ambient-only assignment in older cohorts.")
add(2, sub="BURD", tier="B", basis="Model (CTM / LUR / ML)",
    short="Proposed 3500-MW Virginia gas plant: ~326.5 t/yr primary PM2.5, >1.2 million people exposed, USD 30.5-65 million/yr health damages; project withdrawn",
    design="Integrated emission-air quality-health modelling", pm="Plant-attributable PM2.5 from emission factors of comparable turbines, InMAP dispersion; COBRA health and valuation",
    geo="USA (Virginia, North Carolina)", endpoint="Plant-attributable PM2.5 health and economic burden",
    affil="Politecnico di Milano, Italy; Harvard T.H. Chan School of Public Health, USA",
    n="Health impact assessment of a proposed 3,500-MW natural-gas plant (Pittsylvania County, Virginia) driven by data-centre demand: emissions from operating data of comparable turbines, dispersion with InMAP, health and valuation with EPA COBRA. Estimated ~326.5 tons/yr of PM2.5 raising exposure for >1.2 million people in Virginia and North Carolina; >17,600 county residents would see increments >0.1 ug/m3 over a ~8 ug/m3 background. Annual health-related damages USD 30.5-65 million, falling disproportionately on older, lower-income and racially marginalised communities; the project was withdrawn after the findings were disseminated. Weakness: reduced-form InMAP and COBRA's national concentration-response functions, no uncertainty beyond the damage range, and secondary PM from NOx is handled only through InMAP chemistry. Relevance: increments of 0.1 ug/m3 are far below what any monitor can verify after construction; impact is modelled, never measured.")
add(17, sub="OTHR", tier="B", basis="Satellite-fused",
    short="India NFHS-5 clusters: under-five mortality AOR 1.07 per 10 ug/m3 PM2.5; 1.40 above 80 vs below 40 ug/m3 (preprint)",
    design="Cross-sectional (multistage)", pm="Satellite-derived (NASA) global annual mean PM2.5 linked to NFHS-5 survey clusters; per 10 ug/m3 and categories",
    geo="India (national, NFHS-5)", endpoint="Under-five mortality",
    affil="University of Gour Banga, India; Mamta Health Institute for Mother and Child, India",
    n="Research Square preprint. NFHS-5 (2019-21) births linked at cluster level to NASA satellite-derived annual mean PM2.5; bivariate LISA for spatial clustering and survey-adjusted multivariable logistic regression. Each 10 ug/m3 PM2.5 was associated with adjusted OR 1.07 (95% CI 1.04-1.10) for under-five death; clusters above 80 ug/m3 vs below 40 ug/m3 gave AOR 1.40 (1.17-1.67), with marked spatial heterogeneity. Weakness: one annual PM2.5 value per cluster for deaths spanning five years before the survey, cross-sectional design, and the Indo-Gangetic gradient in PM2.5 tracks poverty and health-system access that survey covariates only partly capture; not peer-reviewed. Relevance: rural India is where satellite products carry the least ground truth - the case for low-cost sensor co-location to anchor these surfaces.")
add(16, sub="RESP", tier="B", basis="Reference / regulatory monitor",
    short="Bangkok AQHI vs 23-hospital OPD 2021-24: poor classifier (AUC 0.35-0.54); same-day respiratory RR 1.023 at AQHI 7 vs median",
    design="Time-series (distributed lag non-linear)", pm="Bangkok AQHI (fixed original coefficients, multipollutant) from city monitoring; PM2.5 comparator; AQHI 7 vs citywide median",
    geo="Thailand (Bangkok)", endpoint="Daily outpatient respiratory, asthma, COPD and ischaemic-stroke morbidity",
    affil="Mahidol University, Thailand; Phramongkutklao Hospital, Thailand",
    n="City-wide time series of outpatient visits at 23 hospitals across 26 postcodes, 1,461 days in 2021-2024; the Bangkok AQHI applied with its original fixed coefficients; ROC analyses for high-morbidity days, negative binomial models per IQR and DLNMs over lags 0-7. Discrimination was poor: fixed-direction AUC 0.353-0.539 for the AQHI and 0.421-0.562 for PM2.5. No consistent log-linear association; DLNMs found a small same-day association at AQHI 7 vs the median for clinically selected respiratory morbidity, RR 1.023 (95% CI 1.004-1.042), surviving Bonferroni and FDR correction; cumulative lag 0-7 associations near null. Weakness: OPD counts include COVID-era service disruption, and many outcome definitions invite multiplicity despite correction. Relevance: an index built from sparse regulatory monitors classifies poorly city-wide; denser sensing is one test of whether exposure misclassification explains it.")
add(6, sub="OTHR", tier="B", basis="Model (CTM / LUR / ML)",
    short="Thailand 77 provinces 2012-2021, 837,616 dengue cases: MERRA-2 dust PM2.5 positively, OC, BC and sulfate inversely associated with incidence",
    design="Bayesian spatiotemporal model", pm="Monthly MERRA-2 reanalysis dust PM2.5, organic carbon, black carbon and sulfate by province",
    geo="Thailand (77 provinces)", endpoint="Monthly provincial dengue incidence",
    affil="Khon Kaen University, Thailand; Khon Kaen University, Thailand",
    n="Ecological analysis of 837,616 dengue cases reported across 77 Thai provinces, 2012-2021, against monthly MERRA-2 aerosol components; Bayesian spatial INLA models adjusted for demographic and temporal factors. Dust PM2.5 was positively associated with dengue incidence, while organic carbon, black carbon and sulfate were inversely associated; the abstract reports no effect sizes or credible intervals. Weakness: ecological province-month design in which aerosol components co-vary with season, rainfall and burning, all of which drive Aedes ecology; MERRA-2 composition at province scale is a reanalysis product with no local validation; mechanism is speculative. Relevance: composition-resolved inputs for disease early warning cannot come from mass-only low-cost sensors; at most they supply total PM2.5 for local calibration of the reanalysis.")
add(12, sub="NEU", tier="B", basis="Not stated",
    short="CHARLS 8806 adults >=60: higher outdoor PM1/PM2.5/PM10 and solid-fuel cooking (global cognition beta -0.57) precede poorer cognition, stronger in rural residents",
    design="Prospective cohort (CHARLS)", pm="Annual mean PM1, PM2.5 and PM10 (source not stated in abstract); household solid fuel for cooking and heating",
    geo="China (national, CHARLS)", endpoint="Global cognition, memory and mental status, 2013-2020",
    affil="Wuhan Mental Health Center, China; Wuhan Mental Health Center, China",
    n="8,806 CHARLS participants aged >=60, 2013-2020; linear mixed-effects models of 2013 exposures on later cognition, stratified by urban-rural residence. Higher outdoor particulate matter was generally associated with poorer subsequent global cognition and memory; 2013 PM2.5 was inversely associated with global cognition in both 2015 and 2018 (coefficients not given in the abstract). Solid-fuel cooking in 2013 predicted lower 2018 global cognition (beta -0.57, 95% CI -0.93 to -0.22), memory (-0.53, -0.77 to -0.31) and mental status (-0.23, -0.40 to -0.06); heating fuel gave similar estimates. Associations were stronger in rural participants. Weakness: household fuel is a binary proxy with no measured indoor PM, attrition in an older cohort is likely exposure- and cognition-related, and outdoor PM effect sizes are not reported. Relevance: rural indoor combustion is where measured personal exposure is thinnest and cheap sensors most informative.")
add(15, sub="REPR", tier="C", basis="Reference / regulatory monitor",
    short="Urumqi 279 mother-infant pairs: longer heating-season gestational overlap linked to shorter birth length (-0.011 cm per day); PAHs detected in 47-91% of plasma samples",
    design="Prospective birth cohort", pm="Gestational overlap with the municipal heating season; ambient PM2.5 and PM10; 16 PAHs in maternal and cord plasma (GC-MS)",
    geo="China (Urumqi)", endpoint="Neonatal anthropometry (length, weight, Ponderal Index)",
    affil="Xinjiang Medical University, China; Xinjiang Medical University, China",
    n="279 mother-infant pairs enrolled June 2019-January 2020 in Urumqi, a coal-heated city; long vs short gestational overlap with the heating season; 16 PAHs by GC-MS in paired maternal and cord plasma. Detection rates were 66-91% in maternal and 48-78% in cord plasma. Longer heating-season exposure was associated with lower birth length (p = 0.002) and Ponderal Index but not birth weight (p = 0.132); each additional day of heating-season overlap was associated with -0.011 cm length (p = 0.004); higher gestational PM2.5 and PM10 also tracked shorter length. No CIs reported. Weakness: heating-season overlap is collinear with season of birth, small n, and enrolment over seven months confounds exposure with calendar time. Relevance: winter coal-heating peaks are steep and spatially patchy - the setting where home-level sensors would replace a seasonal proxy.")
add(9, sub="REPR", tier="C", basis="Genetic / biomarker proxy",
    short="Two-sample MR (UK Biobank exposures, FinnGen outcomes): genetically predicted PM2.5 nominally raises male infertility (p = 0.04), not after Bonferroni; nothing for female infertility",
    design="Two-sample Mendelian randomisation", pm="Genetic instruments for PM2.5, PM2.5-10, PM10, NO2 and NOx (UK Biobank address-based exposures)",
    geo="Global / multi-region", endpoint="Male and female infertility (FinnGen)",
    affil="Second Affiliated Hospital of Jianghan University, China; Second Affiliated Hospital of Jianghan University, China",
    n="Two-sample Mendelian randomisation using instruments for five pollutants from UK Biobank and male and female infertility from FinnGen; four MR estimators plus heterogeneity and pleiotropy tests. Genetically predicted PM2.5 was associated with male infertility at p = 0.04, which did not survive Bonferroni correction; no associations for NOx, NO2, PM10 or PM2.5-10 with male infertility, and none for any pollutant with female infertility. No effect sizes are given in the abstract. Weakness: SNPs associated with a residential pollution estimate index where people live (ancestry, SES, migration), not biological susceptibility, so the exclusion restriction is implausible; the headline result is a nominal p-value. Relevance: none to measurement; it illustrates why genetic proxies cannot substitute for exposure data.")
add(24, sub="NEU", tier="C", basis="Not stated",
    short="DR Congo 721-person cross-sectional sample: poverty, low resilience and depression associated with dementia; PM2.5 not associated (medRxiv)",
    design="Cross-sectional", pm="PM2.5 one of 16 social, behavioural and environmental factors (source not stated in abstract)",
    geo="DR Congo (Kinshasa)", endpoint="Dementia status (including suspected Alzheimer disease)",
    affil="Emory University School of Medicine, USA; University of Navarra, Spain",
    n="medRxiv preprint. 721 participants in the Democratic Republic of the Congo (232 cognitively unimpaired, 489 with dementia including 247 suspected AD); logistic regression on 16 factors with age, sex and missing-category indicators. Adding the factors raised Nagelkerke R2 from 0.106 to 0.368. Poverty (aOR 2.34, 95% CI 1.52-3.60), low resilience (1.84, 1.18-2.86) and depression (1.53, 1.02-2.31) were associated with dementia; higher education inversely (0.51, 0.39-0.66 per SD). PM2.5 exposure was not significantly associated; no estimate is given. Weakness: cross-sectional, non-representative and dementia-enriched sampling, mean imputation, and an unnamed PM2.5 source in a region with almost no ground monitoring. Relevance: Central Africa has near-zero reference monitoring; a null here says more about exposure data than about PM2.5 and dementia.")
add(8, sub="BURD", tier="C", basis="Model (CTM / LUR / ML)",
    short="GBD 2021, adults 40+: ambient PM the largest environmental contributor to subarachnoid-haemorrhage deaths (50,936 in 2021), projected 65,847 by 2050",
    design="Burden of disease (GBD)", pm="GBD 2021 ambient particulate matter, household air pollution, high and low temperature risk factors",
    geo="Global / multi-region", endpoint="Subarachnoid haemorrhage deaths and DALYs attributable to environmental risks",
    affil="Xiangya Hospital, Central South University, China; Xiangya Hospital, Central South University, China",
    n="Secondary analysis of GBD 2021 for adults aged 40+ in 204 countries: SAH burden attributable to ambient PM, household air pollution and temperature extremes, trends 1990-2021, ARIMA and exponential-smoothing projections to 2050 and decomposition. In 2021 ambient PM accounted for 50,936 SAH deaths and 1,357,090 DALYs, more than household air pollution (32,224 deaths) or low temperature (18,648). Ambient-PM-attributable deaths rose from 35,329 in 1990, while household-air-pollution deaths fell from 77,441; projections reach 65,847 ambient-PM deaths by 2050. Burden was higher in males. Weakness: GBD attributable estimates inherit its exposure surfaces and integrated exposure-response curves; the SAH-specific relative risk is borrowed from stroke evidence; no uncertainty intervals in the abstract. Relevance: none directly; GBD surfaces in low-income regions are the least validated by ground sensors.")
add(5, sub="MECH", tier="C", basis="Not stated",
    short="Mouse PM2.5 lung injury: macrophage glycolysis and lactylation drive neutrophil extracellular traps via UBE2Q2/LDHA",
    design="Animal exposure study + in vitro", pm="PM2.5 exposure in mice; dose and particle source not stated in the abstract",
    geo="China (laboratory)", endpoint="PM2.5-induced lung injury; macrophage lactylation and neutrophil extracellular traps",
    affil="Chengdu Institute of Respiratory Health, Southwest Jiaotong University, China; Chengdu Institute of Respiratory Health, Southwest Jiaotong University, China",
    n="Mechanistic study combining single-cell RNA sequencing, surface plasmon resonance, docking and a macrophage-depleted adoptive-transfer mouse model. PM2.5 reprogrammed pulmonary macrophages towards a hyper-glycolytic, lactylation-driven state that paracrinally drove neutrophil chemotaxis and extracellular-trap formation; the E2 enzyme UBE2Q2 acted as the checkpoint regulating LDHA to sustain the cascade, and a plant-derived inhibitor of that axis reduced injury. No exposure-response relationship and no effect sizes with CIs are reported. Weakness: laboratory PM2.5 of unstated origin and concentration, so no dose can be mapped to ambient exposure; the mechanism rests on a single pathway readout. Relevance: none to measurement, but lactylation as an intermediate would need composition-resolved exposure, not mass alone.")
add(19, sub="MECH", tier="C", basis="Lab / research instrument",
    short="Synthetic iron-rich silica core-shell particles raise extracellular GABA and glutamate in rat synaptosomes, size- and dose-dependently (0.1-1.0 mg/ml)",
    design="In vitro", pm="Synthesised Fe3O4@SiO2 core-shell nanoparticles characterised by TEM, SEM, DLS, SAED and XRD; 0.1-1.0 mg/ml",
    geo="Ukraine (laboratory)", endpoint="Extracellular glutamate and GABA levels and ROS generation in rat brain nerve terminals",
    affil="L. V. Pisarzhevskii Institute of Physical Chemistry, National Academy of Sciences, Ukraine; same institute, Ukraine",
    n="Model multipollutant iron-rich silica particles (Fe3O4@SiO2 core-shell, varying constituent proportions) applied to isolated rat brain synaptosomes at 0.1-1.0 mg/ml. Extracellular radiolabelled glutamate and GABA rose with particle size and dose, GABA being the more sensitive readout; the particles reduced spontaneous, H2O2- and kainate-induced ROS generation, interacted with the synaptosomal membrane and added to the effects of Cu2+, Pb2+ and Cd2+ rather than mitigating them. No CIs are reported. Weakness: milligram-per-millilitre doses of synthetic particles are orders of magnitude above realistic deposited lung or brain doses, and synaptosomes bypass every biological barrier. Relevance: supports interest in the iron fraction of ambient PM, which optical sensors cannot see at all.")
add(81, sub="REPR", tier="C", basis="Lab / research instrument",
    short="Rat co-exposure: diesel particulate matter aggravates cyclophosphamide-induced fetal abnormalities and delayed ossification, not uniformly dose-dependent",
    design="Animal exposure study", pm="Diesel particulate matter administered to pregnant rats alongside cyclophosphamide; doses not stated in the abstract",
    geo="Korea (laboratory)", endpoint="Embryo-fetal development; maternal hepatic oxidative-stress markers (MDA, CAT, SOD)",
    affil="Chonnam National University, Republic of Korea; Chonnam National University, Republic of Korea",
    n="Pregnant rats received cyclophosphamide with or without concomitant diesel particulate matter; endpoints were maternal toxicity, fetal weight, morphological alterations and ossification, plus hepatic malondialdehyde and catalase and superoxide-dismutase activities. Cyclophosphamide alone reduced maternal and gravid uterine weight, fetal and placental weight and hepatic antioxidant activity. Added diesel PM aggravated several fetal abnormalities and ossification delay and further lowered maternal catalase and SOD, though responses were not uniformly dose-dependent. No CIs are reported. Weakness: a co-exposure design with a potent chemotherapeutic cannot isolate a PM effect size, non-monotonic responses suggest few animals per dose, and the administration route is not stated. Relevance: none to monitoring; it is an interaction-screening result.")
add(69, sub="MECH", tier="C", basis="Lab / research instrument",
    short="Zinc oxide nanoparticles kill alveolar epithelial cells through lysosomal lipid peroxidation and membrane permeabilization; NRF2 is protective",
    design="Animal exposure study + in vitro", pm="Zinc oxide nanoparticles by oropharyngeal aspiration in mice and in alveolar epithelial cells; doses not stated in the abstract",
    geo="China (laboratory)", endpoint="Alveolar epithelial cell death, lysosomal membrane permeabilization and oxidative stress",
    affil="not stated; not stated",
    n="Oropharyngeal aspiration of ZnO nanoparticles raised pulmonary 4-hydroxynonenal and activated NRF2 in mice, with greater injury and lysosomal change in the alveolar than the bronchial compartment. In vitro, uptake was clathrin- and cholesterol-dependent with lysosomal trafficking; the particles increased lysosomal lipid peroxidation, altered CALPAIN1 and mature CTSB/CTSD and permeabilized lysosomal membranes. N-acetylcysteine and a CTSB inhibitor attenuated injury, while Nrf2 silencing worsened it. No exposure-response or CIs are reported. Weakness: engineered-nanoparticle doses are not anchored to ambient or occupational concentrations, and the comparison across lung compartments is qualitative. Relevance: metal-oxide ultrafines are invisible to optical mass sensors; the relevant exposure metric here is surface area or number.")
add(0, sub="OTHR", tier="C", basis="Not stated",
    short="Wildfire PM2.5 and acute angle-closure, self-controlled case series (metadata only)",
    design="Metadata only: no abstract in Crossref at issue time", pm="Wildfire-period PM2.5 (per title); exposure source not stated",
    geo="USA (California)", endpoint="Acute angle-closure episodes (per title)",
    affil="Stanford Medicine, USA; Byers Eye Institute, Stanford, USA",
    n="Metadata only. The title indicates a self-controlled case series relating PM2.5 exposure during wildfires to acute angle-closure (BMJ Open Ophthalmology, Stanford). No abstract reached the index at issue time, so no finding is asserted. Relevance: a self-controlled design needs daily exposure at the patient address, which during fires varies over kilometres and hours - the regime where regulatory monitors are sparsest and sensor networks or smoke models carry the exposure. Priority recheck when indexed.")
add(11, sub="EXPO", tier="C", basis="Model (CTM / LUR / ML)",
    short="Punjab, Pakistan bottom-up PAH inventory 2015-2024: emissions up 32.8% to 5287 t/yr, domestic coal 53.1% of the total",
    design="Emission inventory", pm="Bottom-up inventory of 16 USEPA priority PAHs by source and fuel, Monte Carlo uncertainty (10,000 iterations); multimedia fate and health-risk assessment",
    geo="Pakistan (Punjab)", endpoint="PAH emissions, multimedia fate and human health risk",
    affil="not stated; not stated",
    n="First source-resolved bottom-up PAH emission inventory for Punjab Province, 2015-2024, built from official Pakistani activity statistics and compiled emission factors with Monte Carlo uncertainty propagation. Total PAH emissions rose from 3,981.5 t in 2015 to 5,287.3 t in 2024 (+32.8%), with no sign of the policy-driven inflection seen in comparable Chinese provinces; domestic coal combustion contributed 53.1% and petroleum combustion 25.7%. Weakness: emission factors are transferred from other countries to Pakistani fuels, stoves and kilns, activity data are provincial aggregates, and the multimedia fate and risk layers compound those uncertainties without validation against measured ambient PAH. Relevance: particle-bound PAH is a combustion-source marker no mass sensor resolves; an inventory of this kind is only testable against filter or online composition measurement.")
add(23, sub="EXPO", tier="B", basis="Review / no primary exposure",
    short="Umbrella review of 18 reviews: time outdoors raises individual exposure, while greenspace, advisories, race and socio-economic status shape community exposure",
    design="Umbrella review / meta-analysis", pm="Ambient air pollution exposure as the outcome of behavioural and social determinants; no single PM metric",
    geo="Global / multi-region", endpoint="Determinants of ambient air pollution exposure",
    affil="Queen's University, Canada; Health Canada, Canada",
    n="Umbrella review of five databases (searched November 2024) covering 18 reviews, with JBI quality appraisal and thematic synthesis, aimed at informing refinement of air quality indices such as Canada's AQHI. Determinants sorted into behaviour (physical activity, travel, protective action) and society (public health, urban planning, neighbourhood and housing, social identity) across 17 subthemes. Time spent outdoors was associated with higher individual exposure; greenspace, public-health advisories, race and socio-economic status shaped community-level exposure. Weakness: a synthesis of heterogeneous reviews with no pooled estimates, so direction is reported without magnitude, and the included reviews share primary studies. Relevance: it argues for behaviour-weighted exposure in index design, which in practice means personal or microenvironment sensing rather than a single station value.")
add(40, sub="SENS", tier="B", basis="Lab / research instrument",
    short="Four Saharan dust events over southwest Germany: ICON-ART within 20 min and 50 m of observed arrival; re-initialization lifts near-surface PM correlation from 0.65-0.69 to 0.86-0.88",
    design="Episode analysis (observations + model)", pm="Lidar depolarization-separated dust backscatter, sun photometer AOD, in situ aerosol size distributions, satellite observations; near-surface PM",
    geo="Germany (southwest)", endpoint="Dust vertical structure, boundary-layer entrainment and model skill",
    affil="Karlsruhe Institute of Technology, Germany; Karlsruhe Institute of Technology, Germany",
    n="Four contrasting Saharan dust events over southwestern Germany evaluated with ground lidar, sun photometer, in situ aerosol measurements, satellites, back trajectories and convection-permitting ICON-ART, including an outbreak with AOD near 1.4. A depolarization method separated dust from other aerosol for like-for-like comparison. ICON-ART reproduced arrival times to about 20 min and layer heights to about 50 m; daily re-initialization raised correlation with observed near-surface PM from 0.65-0.69 to 0.86-0.88, with 2 and 1 km resolution helping mainly in combination with re-initialization. The model overestimated 0.5-2 um particles and underestimated those above 2 um. Weakness: four events at one site, and no CIs on the correlation gains. Relevance: the size-dependent bias is the error any sensor-based dust product inherits, since optical sensors mis-size coarse particles the same way.")
add(41, sub="SENS", tier="C", basis="Low-cost sensor / network",
    short="Low-cost PM sensors tested against aerosols simulating wildland-urban interface fire particles (metadata only)",
    design="Metadata only: no abstract in Crossref at issue time", pm="Low-cost PM sensors challenged with various aerosols simulating WUI fire particles (per title)",
    geo="USA", endpoint="Low-cost PM sensor response across aerosol types (per title)",
    affil="Fire Research Division, National Institute of Standards and Technology, USA; Fire Research Division, NIST, USA",
    n="Metadata only. The title indicates a NIST Fire Research Division investigation of low-cost particulate matter sensors challenged with several aerosols chosen to simulate particles generated in wildland-urban interface fires (Aerosol Science and Technology). No abstract reached the index at issue time, so no finding is asserted. Relevance: direct - aerosol-dependent calibration error is the central limitation of optical low-cost sensors during fires, where burning structures add aerosol types no ambient calibration covers, and this is the record to read in full once indexed.")
add(42, sub="EXPO", tier="C", basis="Reference / regulatory monitor",
    short="Meteorologically normalized PM2.5 as an emission proxy for attributing visibility improvement to emission controls (metadata only)",
    design="Metadata only: no abstract in Crossref at issue time", pm="Meteorologically normalized PM2.5 used as an emission proxy (per title)",
    geo="Not stated (metadata only)", endpoint="Attribution of visibility improvement to anthropogenic emission controls (per title)",
    affil="not stated; not stated",
    n="Metadata only. The title indicates visibility improvements attributed to anthropogenic emission controls using meteorologically normalized PM2.5 as an emission proxy (Atmospheric Environment). No abstract reached the index at issue time, so no finding is asserted. Relevance: weather normalization is the standard way to separate emission change from meteorology in monitoring records, and the same machinery is what any sensor-network trend analysis needs before a policy claim can be made. Recheck for the normalization method and the length of the monitoring series when indexed.")
add(44, sub="EXPO", tier="C", basis="Reference / regulatory monitor",
    short="Long-term trends in air pollutants over major Indian cities (metadata only)",
    design="Metadata only: no abstract in Crossref at issue time", pm="Long-term air pollutant records over major Indian cities (per title); species not specified",
    geo="India (major cities)", endpoint="Long-term pollutant trends (per title)",
    affil="not stated; not stated",
    n="Metadata only. The title indicates an analysis of long-term trends in air pollutants over major cities of India (Atmospheric Environment), from a group at Aryabhatta Research Institute and PRL by author listing. No abstract reached the index at issue time, so no finding is asserted. Relevance: India's regulatory network has expanded rapidly and unevenly, so trend estimates depend heavily on which stations enter when; the same station-availability problem governs whether low-cost networks can extend such series backwards. Recheck for the station set and trend method when indexed.")
add(45, sub="OCC", tier="C", basis="Lab / research instrument",
    short="Real-world particle-bound PAH emissions from inland diesel sightseeing vessels with and without diesel particulate filter retrofit (metadata only)",
    design="Metadata only: no abstract in Crossref at issue time", pm="Real-world particle-bound PAH emissions, DPF-retrofitted vs unretrofitted diesel vessels (per title)",
    geo="Taiwan", endpoint="Particle-bound PAH emission factors and DPF retrofit effect (per title)",
    affil="not stated; not stated",
    n="Metadata only. The title indicates real-world measurement of particle-bound PAH emissions from inland diesel sightseeing vessels and the effect of diesel particulate filter retrofit (Atmospheric Pollution Research). No abstract reached the index at issue time, so no finding is asserted. Relevance: retrofit evaluation on working vessels is exactly the setting where regulatory monitoring is absent and portable or on-board instruments carry the measurement; particle-bound PAH also marks the toxic fraction that mass-only sensors cannot distinguish. Recheck for emission factors and retrofit efficiency when indexed.")
add(46, sub="EXPO", tier="C", basis="Reference / regulatory monitor",
    short="Temporal variability of atmospheric fine particles in Tehran (metadata only)",
    design="Metadata only: no abstract in Crossref at issue time", pm="Atmospheric fine particle concentrations in Tehran (per title); averaging period not stated",
    geo="Iran (Tehran)", endpoint="Temporal variability of fine particles (per title)",
    affil="not stated; not stated",
    n="Metadata only. The title indicates an analysis of the temporal variability of atmospheric fine particles in Tehran, Iran (Atmospheric Pollution Research). No abstract reached the index at issue time, so no finding is asserted. Relevance: Tehran combines basin meteorology, dust intrusion and dense traffic, so hour-to-hour variability is large and a handful of reference stations under-represent it; this is the kind of record that sets the variance a sensor network would have to resolve. Recheck for the monitoring period, station count and whether dust events are separated when indexed.")
add(47, sub="SENS", tier="C", basis="Low-cost sensor / network",
    short="Smoke haze in a northern Thailand mountain-valley region mapped from microsensors plus day-night remote sensing (metadata only)",
    design="Metadata only: no abstract in Crossref at issue time", pm="Microsensor PM network combined with day-night satellite remote sensing (per title)",
    geo="Thailand (northern mountain-valley region)", endpoint="Spatiotemporal variation of smoke haze (per title)",
    affil="not stated; not stated",
    n="Metadata only. The title indicates spatiotemporal analysis of smoke haze in a mountain-valley region of northern Thailand based on microsensors and day-night remote sensing (Aerosol and Air Quality Research, National Central University author listing). No abstract reached the index at issue time, so no finding is asserted. Relevance: direct - a low-cost sensor network fused with satellite retrievals in complex terrain during biomass-burning season is the deployment pattern this digest tracks, and the open questions are co-location, humidity correction and whether night-time retrievals add anything over the sensors. Priority recheck when indexed.")
add(48, sub="EXPO", tier="C", basis="Model (CTM / LUR / ML)",
    short="Eastern Canada PM2.5 emulators: climate change projected to raise the US contribution more than Canadian or Quebec contributions",
    design="Data-fusion / ML surrogate model", pm="Emulators of regional-model PM2.5 response to weather and to emission changes by source region",
    geo="Canada (eastern)", endpoint="Projected PM2.5 attribution between US, Canadian and Quebec emissions",
    affil="Universite de Montreal, Canada; Universite de Montreal, Canada",
    n="Part 2 of a sensitivity study building emulators for the effect of weather changes on PM2.5 in eastern Canada, with projections of how climate change alters the contributions of US, Canadian and Quebec emissions. Only the graphical abstract was indexed at issue time: the US contribution to eastern Canadian PM2.5 is projected to grow more than the domestic contributions. No effect sizes, intervals or emulator skill statistics are available. Weakness: the record is effectively a one-sentence claim at issue time; emulators inherit the parent chemical transport model's biases, and transboundary attribution is sensitive to the emission scenario, which is not stated. Relevance: attribution of this kind cannot be checked by monitors, which see total mass; it matters here because it sets which source regions a Canadian network is actually sampling.")
add(53, sub="SENS", tier="B", basis="Lab / research instrument",
    short="Peroxide-based differential ion chromatography for particulate hydroxymethanesulfonate: 97.5% conversion, 99.6% filter recovery, MDL 0.018 mg/L; archived filters lose ~25% of HMS in a month",
    design="Analytical method validation", pm="PM2.5 filter samples (~180) from a rural North China Plain site; HMS quantified indirectly as sulfate after H2O2 conversion",
    geo="China (North China Plain)", endpoint="Hydroxymethanesulfonate measurement accuracy and ambient concentrations",
    affil="Zhejiang University of Technology, China; Research Center for Eco-Environmental Sciences, Chinese Academy of Sciences, China",
    n="A hydrogen-peroxide differential ion chromatography method quantifies particulate hydroxymethanesulfonate indirectly via the stable sulfate signal. Under optimized conditions (H2O2:HMS >= 4:1, 60 C, 30 min) conversion reached 97.5 +/- 0.3%, spiked-filter recovery 99.6 +/- 1.4% over 0.025-10 mg/L, with a method detection limit of 0.018 mg/L. In ~180 PM2.5 samples from a rural North China Plain site, autumn HMS averaged 0.59 +/- 0.70 ug/m3 (maximum 3.75) and matched or exceeded winter values, tracking high humidity and formaldehyde; archived filters lost about 25% of HMS within a month, implying historical data are biased low. Weakness: single site, indirect quantification that assumes complete and specific conversion, and no inter-laboratory check. Relevance: a storage artefact of this size is a reminder that filter-based reference data used to calibrate sensors carry their own drift.")
add(55, sub="EXPO", tier="C", basis="Model (CTM / LUR / ML)",
    short="WRF-GC coupled to E-AIM: wintertime aerosol pH 2.54-4.32 across six eastern China regions; temperature drives 58-63% of the deviation in southern regions, ammonia 41-58% in high-emission ones",
    design="Chemical transport model", pm="Modelled wintertime PM composition and thermodynamic aerosol pH over six regions of eastern China; ammonia gas-particle partitioning framework",
    geo="China (eastern, six regions)", endpoint="Regional aerosol pH, its drivers and response to ammonia reduction",
    affil="Nankai University, China; Nankai University, China",
    n="WRF-GC coupled with the Extended Aerosol Inorganics Model computes wintertime aerosol pH across six eastern Chinese regions and decomposes regional differences through ammonia gas-particle partitioning. Monthly mean pH spans 2.54-4.32, more acidic in the south. Temperature contributes 58-63% of the regional deviation in the Yangtze River Delta, Pearl River Delta and northeast plain, while ammonia dominates (41-58%) in the high-emission North China and Fenwei plains; negative covariance among drivers damps intramonthly variation. Sensitivity to ammonia reduction rises sharply in ammonia-poor regimes, so large cuts would acidify aerosol more than linearly. Weakness: no observational pH constraint, and pH is not directly measurable, so the result is model-internal. Relevance: aerosol acidity governs secondary formation and metal solubility - properties that drive health effects but are invisible to any mass-based monitor.")
add(61, sub="CVM", tier="C", basis="Not stated",
    short="Developmental near-roadway air pollution exposure with coordinated adiposity and bone-mineral-density changes in early adulthood (metadata only)",
    design="Metadata only: no abstract in Crossref at issue time", pm="Developmental near-roadway air pollution exposure (per title); metric and source not stated",
    geo="Not stated (metadata only)", endpoint="Adiposity and bone mineral density in early adulthood (per title)",
    affil="not stated; not stated",
    n="Metadata only. The title indicates developmental near-roadway air pollution exposure associated with coordinated alterations in adiposity and bone mineral density in early adulthood (Environment International; author listing suggests the southern California children's cohort tradition). No abstract reached the index at issue time, so no finding is asserted. Relevance: near-roadway exposure assigned developmentally is usually modelled from traffic and dispersion rather than measured, and the gradient it represents falls off over tens of metres - the scale at which fixed regulatory monitors are useless and dense or mobile sensing is the only measured alternative. Recheck when indexed.")
add(84, sub="OCC", tier="B", basis="Lab / research instrument",
    short="Downscaled wet spray scrubber on incinerator flue gas: >90% removal of 0.3-7 um particles with 97 um droplets and 10 L/m3 liquid-to-gas; contact time 4-10 s irrelevant",
    design="Engineering control device test", pm="Inlet and outlet particle mass and number size distributions (mode ~0.3 um), metal and carbon content, oxidative potential, SEM morphology",
    geo="France", endpoint="Fractional particle removal efficiency of a wet spraying scrubber",
    affil="not stated; not stated",
    n="A downscaled wet spraying scrubber fed with a slipstream of municipal waste incinerator flue gas was run under nine operating conditions, with particle mass and number measured upstream and downstream and fractional efficiencies computed from number size distributions. Most particles were submicron (mode ~0.3 um) with carbon below 1 wt% and Na and K near 10 wt% each; larger particles carried more metal and higher oxidative potential. Removal exceeded 90% for 0.3-7 um particles with small droplets (nominal D32 97 um) and a high liquid-to-gas ratio (10 L/m3), while gas-spray contact time between 4 and 10 s had no observed effect. Weakness: a downscaled unit on a flue-gas fraction, nine conditions without replication statistics, and no CIs. Relevance: submicron modes with composition-dependent oxidative potential are the fraction optical sensors size worst.")
